 "content": "def transform(grid):
    out=[row[:] for row in grid]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v==0:
                out[r][c]=grid[len(grid)-1-r][c]
    rs=[r for r,row in enumerate(grid) if 0 in row]
    cs=[c for c in range(len(grid[0])) if any(grid[r][c]==0 for r in range(len(grid)))]
    return [[out[r][c] for c in range(min(cs),max(cs)+1)] for r in range(min(rs),max(rs)+1)]
